"import openpyxl
from openpyxl import load_workbook
import shutil

# Copy input file to output
shutil.copy('input.xlsx', 'output.xlsx')

# Load the workbook
wb = load_workbook('output.xlsx')
ws = wb['sheet1']

max_row = ws.max_row

# Read all data from columns A, B, C
all_rows = []
for r in range(1, max_row + 1):
    a_val = ws.cell(row=r, column=1).value
    b_val = ws.cell(row=r, column=2).value
    c_val = ws.cell(row=r, column=3).value
    all_rows.append((r, a_val, b_val, c_val))

# Read helper column J
helper_names = []
for r in range(1, max_row + 1):
    j_val = ws.cell(row=r, column=10).value
    if j_val is not None:
        j_str = str(j_val).strip()
        if j_str != '':
            helper_names.append(j_str)

# Identify and skip header row (assume row 1 is header)
# Skip rows that look like headers (all strings) or are empty
header_row_idx = None
for i, (r, a, b, c) in enumerate(all_rows):
    if isinstance(a, str) and isinstance(b, str) and isinstance(c, str):
        header_row_idx = i
        break

# Build data list, skipping header and empty rows
data = []
for i, (r, a, b, c) in enumerate(all_rows):
    # Skip header
    if header_row_idx is not None and i == header_row_idx:
        continue
    # Skip rows where all values are empty/None
    if (a is None or str(a).strip() == '') and \
       (b is None or str(b).strip() == '') and \
       (c is None or str(c).strip() == ''):
        continue
    data.append((r, a, b, c))

# Remove duplicates based on B and C (both must match)
seen_keys = set()
unique_data = []
for row_data in data:
    r, a, b, c = row_data
    b_key = str(b).strip().lower() if b is not None else ''
    c_key = str(c).strip().lower() if c is not None else ''
    key = (b_key, c_key)
    if key not in seen_keys:
        seen_keys.add(key)
        unique_data.append(row_data)

# Apply sorting logic
if not helper_names:
    # If helper J is empty, sort alphabetically by column B (A-Z)
    unique_data.sort(key=lambda x: (str(x[2]).lower() if x[2] is not None else '', x[0]))
else:
    # Sort by helper column J priority (first entries in J appear first)
    # Within each helper group, keep original order
    # Names not in helper come after, in original order
    priority_map = {name: idx for idx, name in enumerate(helper_names)}

    def sort_key(item):
        r, a, b, c = item
        b_str = str(b).strip() if b is not None else ''
        if b_str in priority_map:
            # In helper: sort by helper order, then by original row
            return (0, priority_map[b_str], r)
        else:
            # Not in helper: preserve original order
            return (1, 0, r)

    unique_data.sort(key=sort_key)

# Final requirement: sort only column H (which is column C from source) lowest to highest
# Convert column C values to comparable numbers
def get_h_sort_key(item):
    r, a, b, c = item
    if isinstance(c, (int, float)):
        return (c, r)
    elif c is None:
        return (float('inf'), r)
    else:
        # Try to convert string to number
        try:
            return (float(str(c).strip()), r)
        except (ValueError, TypeError):
            return (float('inf'), r)

unique_data.sort(key=get_h_sort_key)

# Write output to F2:H10 (9 rows available)
output_rows = 9
for i in range(output_rows):
    target_row = i + 2
    if i < len(unique_data):
        r, a, b, c = unique_data[i]
        ws.cell(row=target_row, column=6, value=a)  # F = Column A
        ws.cell(row=target_row, column=7, value=b)  # G = Column B
        ws.cell(row=target_row, column=8, value=c)  # H = Column C
    else:
        # Clear any existing values beyond data
        for col in [6, 7, 8]:
            ws.cell(row=target_row, column=col, value=None)

wb.save('output.xlsx')
print("Sorting completed. Output saved to output.xlsx")"
